        shutil.rmtree(self.tmp_path, ignore_errors=False)
    except OSError as exc:
        if not self.tmp_path.exists():
            return
        raise AssertionError(
            f"could not remove temporary directory {self.tmp_path} "
            f"during test teardown: {exc!r}"
        ) from exc
