import sys, unittest
import multiprocessing as mp
sys.path.insert(0, ".")

def build(mode):
    loader = unittest.TestLoader()
    if mode == "reverse":
        names = ["tests.test_vault", "tests.test_concurrency",
                 "tests.test_reload_regression", "tests.test_windows_lock"]
        flat = []
        def collect(s):
            for t in s:
                if isinstance(t, unittest.TestSuite): collect(t)
                else: flat.append(t)
        for n in names: collect(loader.loadTestsFromName(n))
        flat.reverse()
        return unittest.TestSuite(flat)
    if mode == "pick":
        names = [
            "tests.test_windows_lock.TestWindowsEntryContract.test_rejections_raise_exactly_and_allocate_nothing",
            "tests.test_vault.TestClose.test_close_releases_lock_handle_and_is_idempotent",
            "tests.test_vault.TestMultiProcess.test_lock_file_is_not_vault_content",
            "tests.test_reload_regression.TestRevocationJournalReloadFailures",
            "tests.test_concurrency.TestEntryPointContract.test_duplicate_revoke_and_repoint_at_active_are_value_errors",
        ]
        return unittest.TestSuite(loader.loadTestsFromName(n) for n in names)

if __name__ == "__main__":
    mp.set_start_method("fork", force=True)
    result = unittest.TextTestRunner(verbosity=1).run(build(sys.argv[1]))
    sys.exit(0 if result.wasSuccessful() else 1)

